  "inlineSchema": "// Ubique Systems — data model\n//\n// Provider is SQLite so the site runs with zero setup on a laptop. Every model\n// below is Postgres-compatible: switch `provider` to \"postgresql\" and point\n// DATABASE_URL at a managed instance to deploy. Nothing here uses a\n// SQLite-only type.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n/// Someone who can sign in to /admin.\nmodel AdminUser {\n  id           String    @id @default(cuid())\n  email        String    @unique\n  name         String\n  passwordHash String\n  role         String    @default(\"editor\") // \"owner\" | \"editor\"\n  lastLoginAt  DateTime?\n  createdAt    DateTime  @default(now())\n\n  sessions Session[]\n  notes    ApplicationNote[]\n  invites  AdminInvite[]     @relation(\"InvitesSent\")\n}\n\n/// A signed-in browser session. Deleted on sign-out and swept when expired.\nmodel Session {\n  token     String   @id\n  userId    String\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n\n  user AdminUser @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([expiresAt])\n}\n\n/// A published (or draft) vacancy.\nmodel Job {\n  id    String @id @default(cuid())\n  /// URL segment — /careers/<slug>. Unique and stable once published.\n  slug  String @unique\n  title String\n\n  department     String\n  location       String\n  employmentType String // Full Time | Contract | Part Time ...\n  workplace      String // On-site | Hybrid | Remote\n  experience     String\n\n  description String\n\n  /// JSON string arrays. SQLite has no native array type; Postgres would use\n  /// String[]. Read and written through the helpers in lib/jobs.ts so callers\n  /// always see real arrays.\n  responsibilities String @default(\"[]\")\n  requirements     String @default(\"[]\")\n  technologies     String @default(\"[]\")\n\n  /// DRAFT hides it everywhere. OPEN publishes it. CLOSED keeps the page\n  /// alive for existing links but stops applications.\n  status String @default(\"DRAFT\")\n\n  postedAt     DateTime  @default(now())\n  validThrough DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  applications Application[]\n\n  @@index([status])\n  @@index([postedAt])\n}\n\n/// A candidate's submission against a job.\nmodel Application {\n  id        String @id @default(cuid())\n  /// Human-quotable reference shown to the candidate and in the notification.\n  reference String @unique\n\n  jobId String\n  job   Job    @relation(fields: [jobId], references: [id], onDelete: Cascade)\n\n  firstName String\n  lastName  String\n  email     String\n  phone     String\n  location  String\n\n  linkedin  String @default(\"\")\n  coverNote String @default(\"\")\n\n  /// CV lives on disk (or object storage); the row keeps the metadata.\n  cvFilename String\n  cvMimeType String\n  cvSize     Int\n  cvPath     String\n\n  consent Boolean @default(false)\n\n  /// NEW | REVIEWING | SHORTLISTED | INTERVIEWING | OFFERED | REJECTED | HIRED\n  status String @default(\"NEW\")\n\n  /// Set when the notification email actually went out.\n  notifiedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  notes ApplicationNote[]\n\n  @@index([jobId])\n  @@index([status])\n  @@index([createdAt])\n  @@index([email])\n}\n\n/// Recruiter comment on an application.\nmodel ApplicationNote {\n  id            String  @id @default(cuid())\n  applicationId String\n  /// Null once the author's account is removed. Notes are institutional\n  /// record — losing a screening comment because someone left the company is\n  /// worse than showing \"Removed user\" against it.\n  authorId      String?\n\n  body String\n\n  createdAt DateTime @default(now())\n\n  application Application @relation(fields: [applicationId], references: [id], onDelete: Cascade)\n  author      AdminUser?  @relation(fields: [authorId], references: [id], onDelete: SetNull)\n\n  @@index([applicationId])\n}\n\n/// A pending invitation to join the admin.\n///\n/// Invites exist so an owner never has to know anyone else's password: the\n/// invitee follows a one-time link and sets their own. The link can be sent by\n/// any channel — it doesn't depend on the site's email being configured.\nmodel AdminInvite {\n  id    String @id @default(cuid())\n  email String @unique\n  name  String\n  role  String @default(\"editor\")\n\n  /// Random, single-use, and the only thing that authorises acceptance.\n  token String @unique\n\n  invitedById String\n  invitedBy   AdminUser @relation(\"InvitesSent\", fields: [invitedById], references: [id], onDelete: Cascade)\n\n  expiresAt  DateTime\n  acceptedAt DateTime?\n  createdAt  DateTime  @default(now())\n\n  @@index([expiresAt])\n}\n\n/// Newsletter signup from the site footer.\nmodel Subscriber {\n  id    String @id @default(cuid())\n  email String @unique\n\n  /// Which page they subscribed from — useful for judging what draws people in.\n  source String @default(\"footer\")\n\n  /// Unsubscribe happens by token, never by guessing the row id.\n  unsubscribeToken String    @unique\n  unsubscribedAt   DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@index([createdAt])\n}\n"
